{
 "app_name": "amazon",
 "api_name": "search_products",
 "path": "/amazon/products",
 "method": "GET",
 "description": "Search for products with a query and various filtering criteria.",
 "parameters": [
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "product_type",
   "type": "string",
   "required": false,
   "description": "The type of product to search for.",
   "default": null,
   "constraints": []
  },
  {
   "name": "color",
   "type": "string",
   "required": false,
   "description": "The color of product to search for.",
   "default": null,
   "constraints": []
  },
  {
   "name": "relative_size",
   "type": "string",
   "required": false,
   "description": "The relative size of product to search for.",
   "default": null,
   "constraints": [
    "value in ['extra-small', 'small', 'medium', 'large', 'extra-large']"
   ]
  },
  {
   "name": "min_price",
   "type": "number",
   "required": false,
   "description": "The minimum price for search results.",
   "default": 0.0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "max_price",
   "type": "number",
   "required": false,
   "description": "The maximum price for search results.",
   "default": 9.223372036854776e+18,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "min_product_rating",
   "type": "number",
   "required": false,
   "description": "The minimum product rating for search results.",
   "default": 0.0,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "max_product_rating",
   "type": "number",
   "required": false,
   "description": "The maximum product rating for search results.",
   "default": 5.0,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "min_seller_rating",
   "type": "number",
   "required": false,
   "description": "The minimum seller rating for search results.",
   "default": 0.0,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "max_seller_rating",
   "type": "number",
   "required": false,
   "description": "The maximum seller rating for search results.",
   "default": 5.0,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "seller_id",
   "type": "integer",
   "required": false,
   "description": "ID of the seller to search for.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the products by prefixed with +/- to reflect ascending/descending. Valid attributes: rating, price and delivery_days. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "product_id": 1,
    "seller_id": 1,
    "product_type": "string",
    "name": "string",
    "description": "string",
    "price": 0.0,
    "delivery_days": 1.0,
    "inventory_quantity": 0.0,
    "weight": 0.0,
    "length": 0.0,
    "width": 0.0,
    "height": 0.0,
    "color": "string",
    "relative_size": "extra-small",
    "rating": 0.0,
    "num_product_reviews": 1,
    "num_product_questions": 1,
    "shareable_link": "string",
    "variations": [
     {
      "product_id": 1,
      "relative_size": "extra-small",
      "color": "string"
     }
    ]
   }
  ],
  "failure": {
   "message": "string"
  }
 }
